from contextlib import contextmanager
from typing import Generator

from sglang.srt.debug_utils.comparator.output_types import GeneralWarning


class WarningSink:
    """Collects :class:`GeneralWarning` records within a scoped context.

    Mirrors :class:`sglang.srt.debug_utils.comparator.log_sink.LogSink`: nested
    ``context()`` blocks capture warnings emitted via ``add`` into a bucket.
    Warnings added outside any context are routed to the report sink so they
    are still surfaced.
    """

    def __init__(self) -> None:
        self._stack: list[list[GeneralWarning]] = []

    @contextmanager
    def context(self) -> Generator[list[GeneralWarning], None, None]:
        bucket: list[GeneralWarning] = []
        self._stack.append(bucket)
        try:
            yield bucket
        finally:
            popped = self._stack.pop()
            assert popped is bucket

    def add(self, warning: GeneralWarning) -> None:
        if self._stack:
            self._stack[-1].append(warning)
        else:
            from sglang.srt.debug_utils.comparator.output_types import (
                LogRecord,
                report_sink,
            )

            report_sink.add(LogRecord(infos=[], errors=[]))


warning_sink = WarningSink()
